import selfies as sf
from rdkit import Chem
from rdkit.Chem import Descriptors, rdMolDescriptors
large='[C][C][C][C][O][C][C][O][C][=C][C][=C][Branch2][=Branch1][Branch2][C][=C][C][=C][C][=Branch1][Ring2][=C][Ring1][=Branch1][C][=C][Branch2][Ring2][#Branch1][C][=Branch1][C][=O][N][C][=C][C][=C][Branch1][=N][C][Branch1][C][O][C][=C][C][=C][C][=N][Ring1][=Branch1][C][Branch1][=Branch2][C][Branch1][C][F][Branch1][C][F][F][=C][Ring2][Ring1][C][C][C][N][Ring2][Ring1][=N][C][=Branch1][C][=O][C][Branch1][C][F][Branch1][C][F][F][C][=C][Ring2][Ring2][N]'
small='[O][=C][Branch1][Ring1][O][O][C][=C][C][=C][C][Branch1][C][Cl][=C][Ring1][#Branch1]'
for name,x in [('large',large),('small',small)]:
    try:
        smi=sf.decoder(x)
        m=Chem.MolFromSmiles(smi)
        print(name,'SMILES',smi)
        print('valid',m is not None,'formula',rdMolDescriptors.CalcMolFormula(m) if m else None,'atoms',m.GetNumAtoms() if m else None)
        if m:
            for a in m.GetAtoms():
                if a.GetSymbol() in ['N','O','Cl']:
                    print(a.GetIdx(),a.GetSymbol(),'Hs',a.GetTotalNumHs(),'degree',a.GetDegree(),'charge',a.GetFormalCharge())
    except Exception as e: print(name,'ERROR',type(e).__name__,str(e))
